struct stat sb;

// File creation implicitly sets ownership
int fd = open("new_file", O_CREAT | O_WRONLY, 0644); 

if (fd != -1) {
    fstat(fd, &sb);
    close(fd);
}

/* Resulting UID: */
uid_t file_uid = sb.st_uid;
// Always equals the effective user ID (geteuid())

/* Resulting GID: */
gid_t file_gid = sb.st_gid;
// Varies: Often effective group ID (getegid())
// OR parent directory GID (if parent has S_ISGID set)

uid_t current_euid = geteuid();
gid_t current_egid = getegid();
